/**
 * Every comment on one issue, with no page cap. Thread shape is irrelevant
 * here: a reply whose parent was deleted is still its own row and is included
 * when `scope` asks for live rows only.
 */
export async function listCommentsForIssue(
  orgId: OrgId,
  issueId: IssueId,
  scope: ArchiveScope = {},
): Promise<readonly Comment[]> {
  const rows = getDb()
    .select()
    .from(comments)
    .where(
      and(
        ...compact(
          orgPredicate(comments.orgId, orgId),
          eq(comments.issueId, issueId),
          livePredicate(comments.archivedAt, scope),
        ),
      ),
    )
    .orderBy(asc(comments.createdAt), asc(comments.id))
    .all();

  return rows.map(toComment);
}

/** Live comments only. A reply counts as its own comment; a deleted one does not. */
export async function countComments(
  orgId: OrgId,
  issueId: IssueId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(comments)
    .where(
      and(
        ...compact(
          orgPredicate(comments.orgId, orgId),
          eq(comments.issueId, issueId),
          livePredicate(comments.archivedAt, {}),
        ),
      ),
    )
    .get();
  return row?.value ?? 0;
}

