subscribe("issue.archived", async (payload) => {
  await removeFromIndex(payload.orgId, "issue", payload.issueId);
  // Comments are indexed under their own ids, so dropping the issue
  // document leaves the thread searchable. Remove every comment on this
  // issue, including ones already soft-deleted, and nothing else.
  const comments = await commentRepo.listCommentsForIssue(
    payload.orgId,
    payload.issueId,
    { includeArchived: true },
  );
  for (const comment of comments) {
    await removeFromIndex(payload.orgId, "comment", comment.id);
  }
