import { createLogger } from "@/lib/logger";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import {
  indexComment,
  indexIssue,
  indexProject,
} from "@/server/services/search-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId, Page } from "@/types/common";

/**
 * Rows read per page while walking the org's content.
 * Repository listings are hard-capped at this size, so the walk must follow
 * `nextCursor` until it is exhausted — a single page drops the oldest rows.
 */
const PAGE_SIZE = 100;

const logger = createLogger("search-reindex-job");

/**
 * Visits every row of a cursor listing. Stops when the cursor stops advancing
 * so a stuck page cannot loop forever.
 */
async function eachPage<T>(
  load: (cursor: string | null) => Promise<Page<T>>,
  visit: (item: T) => Promise<void>,
): Promise<void> {
  let cursor: string | null = null;
  const seenCursors = new Set<string>();

  for (;;) {
    const page = await load(cursor);
    for (const item of page.items) {
      await visit(item);
    }

    const next = page.nextCursor;
    if (page.items.length === 0 || next === null || next === cursor || seenCursors.has(next)) {
      return;
    }
    seenCursors.add(next);
    cursor = next;
  }
}

/**
 * Rebuilds one tenant's search index from its live content only: live
 * projects, non-archived issues, and non-deleted comments on those issues
 * (a live reply whose parent was deleted is still live). The previous index
 * for this org is replaced, so a second run cannot leave duplicates or
 * resurrect archived issues and deleted comments. Other workspaces are not
 * touched.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    await searchRepo.deleteSearchDocumentsForOrg(orgId);

    await eachPage(
      (cursor) =>
        projectRepo.listProjects({
          orgId,
          limit: PAGE_SIZE,
          cursor,
          includeArchived: false,
        }),
      async (project) => {
        try {
          await indexProject(orgId, project);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index project", {
            projectId: project.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      },
    );

    await eachPage(
      (cursor) =>
        issueRepo.listIssues({
          orgId,
          limit: PAGE_SIZE,
          cursor,
          includeArchived: false,
        }),
      async (issue) => {
        try {
          await indexIssue(orgId, issue);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }

        let comments: readonly Awaited<
          ReturnType<typeof commentRepo.listCommentsForIssue>
        >[number][] = [];
        try {
          comments = await commentRepo.listCommentsForIssue(orgId, issue.id);
        } catch (error) {
          result.failed += 1;
          logger.error("failed to list comments", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
          return;
        }

        for (const comment of comments) {
          try {
            await indexComment(orgId, comment);
            result.processed += 1;
          } catch (error) {
            result.failed += 1;
            logger.error("failed to index comment", {
              issueId: issue.id,
              commentId: comment.id,
              reason: error instanceof Error ? error.message : String(error),
            });
          }
        }
      },
    );
  });
}

