 * `nextCursor` until it is exhausted — a single page drops the oldest rows.
 */
const PAGE_SIZE = 100;

const logger = createLogger("search-reindex-job");

/**
 * Visits every row of a cursor listing. Stops when the cursor stops advancing
 * so a stuck page cannot loop forever.
 */
async function eachPage<T>(
  load: (cursor: string | null) => Promise<Page<T>>,
  visit: (item: T) => Promise<void>,
): Promise<void> {
  let cursor: string | null = null;
  const seenCursors = new Set<string>();

  for (;;) {
    const page = await load(cursor);
    for (const item of page.items) {
      await visit(item);
    }

    const next = page.nextCursor;
    if (page.items.length === 0 || next === null || next === cursor || seenCursors.has(next)) {
      return;
    }
    seenCursors.add(next);
    cursor = next;
  }
}

